import type { KnowledgeArticle } from './knowledge-article-model';
import type { KnowledgeVersion } from './knowledge-version-model';
import type { Person } from './person-model';
import type { Workspace } from './workspace-model';

export interface KnowledgeFeedback {
  /**
   * @displayName Knowledge Feedback ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Feedback Label
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  feedbackLabel: string;
  /**
   * @displayName Comments
   */
  comments?: string;
  /**
   * @displayName Created At
   * @validationRule Required for create/update operations
   */
  createdAt: string;
  /**
   * @displayName Helpful
   * @validationRule Required for create/update operations
   */
  helpful: boolean;
  /**
   * @displayName Knowledge Article
   * @validationRule Required for create/update operations
   */
  knowledgeArticle: Pick<KnowledgeArticle, 'id' | 'articleNumber'>;
  /**
   * @displayName Knowledge Version
   */
  knowledgeVersion?: Pick<KnowledgeVersion, 'id' | 'immutableSnapshotLabel'>;
  /**
   * @displayName Person
   * @validationRule Required for create/update operations
   */
  person: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _KnowledgeFeedback = 'KnowledgeFeedback' as const;